85.docs:
Builds a row from an iterator over strings.

# Examples

```
# use tabular::*;
use std::fmt::Display;

struct Matrix<'a, T: 'a> {
    width:  usize,
    height: usize,
    data:   &'a [T],
}

impl<'a, T: Display> Display for Matrix<'a, T> {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        let ncols = self.width;
        let row_spec: String =
             std::iter::repeat("{:>} ".chars()).take(ncols).flat_map(|x| x).collect();

        let mut table = Table::new(row_spec.trim_end());

        for row_index in 0 .. self.height {
            table.add_row(Row::from_cells(
                self.data[row_index * ncols ..]
                    .iter().take(ncols)
                    .map(|elt: &T| elt.to_string())));
        }

        write!(f, "{}", table)
    }
}

print!("{}", Matrix {
    width:   3,
    height:  2,
    data:    &[1, 23, 456, 7890, 12345, 678901],
});
```

159.docs:
A macro for building a [`Table`].

`table!(S, A, B, C)` is equivalent to
`Table::new(S).with_row(A).with_row(B).with_row(B)`.

# Examples

```
use tabular::{row, table};

# fn main() {
let table = table!("{:>}  {:<}  {:<}",
                   row!(34, "hello", true),
                   row!(567, "goodbye", false));

assert_eq!( format!("\n{}", table),
            r#"
 34  hello    true
567  goodbye  false
"# );
# }
```

